    "ck.nochat": "Open a conversation to see its checkpoints. The setting above applies to every conversation.",
    "ck.total": "{0} checkpoints, {1} in all.", "ck.none": "No checkpoint yet.", "ck.failed": "Not done: {0}",
    "sl.d.checkpoints": "Show or change whether file checkpoints are taken",
    "sl.ck.usage": "Checkpoints are: {0}. Use /checkpoints on, soft, off or default.", "sl.ck.now": "Checkpoints: {0}.",
    "cs.perm": "What the agent may do without asking", "cs.perm.help": "For the next new conversation. A command rule lets that kind of command run without asking; in a question, \"Always allow\" adds one for you.", "ch.answers": "Answers", "ch.answered": "You answered: {0}",
    "ch.payment.waiver": "Paid by your standing permission: {0} to {1} (site: {2}); {3} left.", "ch.payment.confirmed": "Payment you confirmed: {0} to {1} (site: {2}).",
    "ch.q.plan_approval": "Approve this plan and go on in '{0}' mode?\n\n{1}", "ch.q.plan_outside": "The agent read content from outside this conversation before it wrote this plan.",
