    "ch.retrying": "The model cannot answer now. New try {0} in {1} s; it keeps trying until you stop it.", "ch.restarting": "The agent stopped and is being started again (try {0}, in {1} s); it goes on from where it was and is told the last call may have run.",
    "ch.pending.h": "{0}The agent went on with other work. Your answer is applied when you give it, even later or from the phone.", "ch.pending.src.people": "This involves another person. ", "ch.pending.src.resource": "This involves money or a resource that is not yours alone. ", "ch.pending.src.booking": "This involves a booking. ",
    "ch.ask.send": "Send answers", "ch.ask.send.tip": "Send your answers to the agent (Ctrl+Enter).", "ch.ask.skip": "Skip",
