    "ch.ask.free.ph": "Write your answer", "ch.ask.answered": "You answered:", "ch.ask.skipped": "You skipped the questions: the agent decides and says what it assumed.",
    "ch.ask.in_chat": "You will answer in the chat.", "ch.ask.closed": "Closed: you answered in the chat.", "ch.ask.noanswer": "(no answer)",
    "ch.suggest.label": "Suggested next messages", "ch.suggest.tip": "Puts this in the message box: {0}. Nothing is sent until you press Send.", "ch.suggest.use": "Put in the message box: {0}",
    "ch.suggest.dismiss": "Hide the suggestions", "ch.intake.assumed": "Assumed, because the message did not say: {0}.", "ch.intake.parts": "Large request, {0} parts recorded in the task list: {1}.",
    "ch.intake.parked": "Left for you to decide: {0}.", "iq.title": "Questions and suggestions",
    "sub.inference": "Inference", "ps.title": "Prompt analysis", "ps.off": "Off", "ps.rules": "Rules", "ps.full": "Full",
    "ps.intro": "How your message is looked at before the model starts on it. Your own words are always kept exactly as you wrote them. The same switch is on the Chat page; both always show the same value, and a running conversation takes a change from its next message.",
    "ps.off.d": "Your message goes to the model exactly as you wrote it. Nothing is checked or changed.",
    "ps.rules.d": "Quick checks, no extra model call. It removes invisible characters and extra blank lines, writes the real date next to words like 'tomorrow', and reminds the model when you listed several items. It costs nothing.",
    "ps.full.d": "Everything in Rules, and the model also reads your request first to see whether something is missing or risky. It may ask you a short question before it starts. It adds a few seconds to each message.",
    "ps.help": "What the three states do", "ps.current": "selected", "pal.set.prompt": "Prompt analysis: how each request is looked at first",
    "iq.defaults": "Default values", "iq.defaults.tip": "Back to Off, suggestions on and the default size.",
    "iq.sugg.title": "Next-message suggestions", "iq.sugg.on": "Suggest what to write next", "iq.sugg.help": "After an answer, a few short suggestions appear under it. A click only puts the text in the message box: you edit it or press Send. It costs one short model call, made only when nothing else is waiting, and never in unattended runs.",
    "iq.size.title": "Extra model calls and long conversations", "iq.size": "Longest conversation, in tokens", "iq.size.help": "The extra calls (the check of a request in Full mode and the suggestions) are not made in a conversation longer than this, because a long one may lose its cached start and the next answer would be slower. Raise it if you do not mind; lower it to be safe.",
