    "pv.loaded": "Loaded:", "pv.noneLoaded": "nothing", "pv.usedBy": "used by {0}",
    "pv.functions": "Which provider each function uses",
    "pv.functions.help": "Only Basalt's own functions are listed. Other programs that use this server still see the loaded model and nothing else. A function that handles your personal data cannot use a provider outside this PC unless you say yes for it.",
    "pv.council": "Council",
    "pv.council.help": "The Council functions above are advisers that debate a hard question one after another; the moderator ends the debate when it says they agree, or when the rounds run out. Give each a name and a job, and choose how many rounds at most.",
    "pv.council.rounds": "Rounds at most",
    "pv.council.rounds.help": "From 1 to {0}. Each round is every adviser speaking once and then the moderator.",
