    "cp.title": "Capabilities and visual analysis", "cp.help": "Skills, plugins and MCP servers found on this PC (names, descriptions and commands only: no key is read). What is found is usable at once unless you turn it off. The agent looks them up when it needs one, so they do not fill its prompt.",
