    "gt.title": "Checks before an answer ends", "gt.saved": "Saved.", "gt.save": "Save", "gt.defaults": "Back to the defaults", "gt.e.offline": "The server did not answer.",
    "gt.verify.title": "The project's own checks", "gt.verify.help": "When the agent has changed files and is about to give its answer, these commands can run first. If one fails, its output goes back to the agent, which fixes the cause and answers again. Off unless you turn it on.",
    "gt.commands": "Check commands", "gt.commands.help": "One command per line (at most {0}), for example the tests or a linter. They run in the conversation's folder like any command the agent runs, and listing one here approves that exact command: it never asks. Only this PC can change the list.",
    "gt.mode": "When they run", "gt.mode.off": "Never", "gt.mode.unattended": "Only when nobody is watching (routines, headless runs)", "gt.mode.always": "Always, in every conversation",
    "gt.mode.help": "Never is the default. Choose the middle one to let an unattended run check itself without slowing the conversations you follow.",
    "gt.rounds": "Fixes allowed", "gt.rounds.help": "How many times a failed check sends the agent back to fix it, 1 to 3. The run also stops when the same failure comes back unchanged, or when a command cannot run at all (a missing tool, no tests found).",
    "gt.nocommands": "The gate is on but no command is listed, so nothing will be checked.",
    "gt.end.title": "When a budget runs out, and model errors", "gt.grace": "Warn before a budget runs out and allow one last report", "gt.grace.help": "When the steps, tokens or time of an answer are nine tenths used the agent is told; when they run out it gets one more reply, without tools, to say what is done and what is not. Turn off to cut the answer at once.",
    "gt.class": "Proposal: end the turn on an error that waiting cannot cure", "gt.class.help": "Awaiting the owner's decision, off by default. Today every failed model call is retried without end. With this on, a request the model server will always refuse (a malformed request, a refused key) ends the turn and shows the error instead; busy, loading, rate-limited and unreachable servers are still waited for.",
    "cd.role": "Role",
    "cd.role.tip": "What the agent is for in this conversation. It decides which tools the agent may use and the working rules it is told. You can change it at any time; the conversation goes on.",
    "cd.role.build": "Developer",
    "cd.role.build.d": "Developer: reads, searches, edits files and runs the project's checks. The usual role for changing code.",
    "cd.role.plan": "Plan",
    "cd.role.plan.d": "Plan: reads and asks, and writes only a plan under .basalt/plans. It changes nothing else and runs nothing.",
    "cd.role.ask": "Ask",
    "cd.role.ask.d": "Ask: answers questions about the project. It reads and searches; it cannot change files or run commands.",
    "cd.role.debug": "Debug",
    "cd.role.debug.d": "Debug: like Developer, but it finds and confirms the cause of a fault before it fixes it.",
    "cd.role.orchestrate": "Orchestrate",
    "cd.role.orchestrate.d": "Orchestrate: splits the work among subagents and checks what they bring back. It does not edit files or run commands itself.",
    "cd.role.general": "General",
    "cd.role.general.d": "General: no limit on tools, as in the Chat. Use it for browsing, planning documents or anything that is not code.",
