    "cx.title": "Long work: summarising older steps", "cx.saved": "Saved.", "cx.save": "Save", "cx.defaults": "Back to the defaults", "cx.e.offline": "The server did not answer.",
    "cx.on": "Summarise the older steps when the context is nearly full",
    "cx.on.help": "While the agent works through many steps in one request, its conversation grows. Old tool results are first replaced by short notes (nothing is lost: the full text is saved). If the conversation is still near the limit, the older steps become a summary that the model writes in a separate call, and the newest steps stay as they were written. The system prompt and the tool list never change. Off: only the masking of old results remains, and a request that outgrows the window can fail.",
    "cx.threshold": "Start at (% of the prompt budget)",
    "cx.threshold.help": "The share of the room the conversation may use before the older steps are summarised, 50 to 98. It never starts before old results are masked (the Chat threshold). Lower starts sooner and keeps more room free; higher keeps more detail and leaves less margin. The default is 85.",
    "cx.cost": "Each summary is one extra model call, and the server reads the shortened conversation again after it; the size of that is shown in the chat and by /context.",
    "ch.ev.compaction": "Earlier steps were summarised: {0} to {1} tokens; the server reads about {2} of them again.", "ch.ev.compaction_cache": "After the summary the server took {1} of {0} tokens from its cache.",
    "sl.r.cx.off": "Summaries of older steps are off.", "sl.r.cx.on": "Summaries start at {0}% of the budget; made so far: {1}.",
    "sl.r.cx.last": "Last one: {0} to {1} tokens, {2} messages replaced, written by {3}.", "sl.r.cx.by.model": "the model", "sl.r.cx.by.extract": "a plain extract",
    "sl.r.cx.prefix": "Start kept as it was: {0} tokens; read again by the server: {1}.", "sl.r.cx.observed": "Server cache after it: {0} of {1} tokens.", "sl.r.cx.reread": "Not in the summary, to read again: {0}.",
    "kn.notes.title": "Project notes added to a request",
    "kn.notes.help": "The agent keeps short notes about a project (what it remembers). At each request only the notes that share enough with what you wrote are added, after your message and as data. The conversations that work in copies of one repository share the same notes.",
    "kn.score": "Points a note must score", "kn.score.help": "Each word of your request that a note also has scores up to 1 point (less the more notes have it); a specific word such as sm_120 or e-mail scores up to 2. Common words (the, and, il, di) never count. A note is added when its points reach this number; a short request of up to three words is also answered by a note that has them all. Higher: fewer notes, more precise. 0: the best matches whatever they share.",
    "kn.count": "Most notes per request", "kn.count.help": "At most this many notes are added to one request. 0: none is added by itself (the agent can still look for them).",
    "kn.budget": "Most tokens for the notes", "kn.budget.help": "The notes added to one request never take more than this many tokens of the context. A note that does not fit is left out.",
    "kn.wiki.title": "Wiki (wikibridge)", "kn.wiki.help": "A knowledge wiki that runs on this PC or your network. When it is on, the Chat, the Agent and the plan steps that ask the wiki can search it and read its pages. What it returns is treated as data, not as orders.",
    "kn.wiki.on": "Offer the wiki to the Chat and the Agent", "kn.wiki.url": "Address of the wikibridge", "kn.wiki.url.help": "Where the service answers, for example http://127.0.0.1:8775. Empty: the address in BASALT_WIKIBRIDGE_URL, else that one. If the service asks for a key, set BASALT_WIKIBRIDGE_KEY on this PC.",
    "kn.wiki.project": "Project of the wiki", "kn.wiki.project.help": "The project (slug) used when a request names none. Empty: the first one the wiki lists.",
    "kn.wiki.check": "Check the connection", "kn.wiki.checking": "Asking the wiki...", "kn.wiki.ok": "The wiki answers at {0} ({1} projects).", "kn.wiki.bad": "The wiki did not answer at {0}: {1}",
    "kn.ref.title": "Reference documents (RAG and CAG)", "kn.ref.help": "A folder of .md and .txt documents the agent can use. Small sets are put whole at the start of the conversation (CAG, fast but they fill the context); large ones are searched and only the passages that match arrive (RAG). They apply to the conversations that start after you save.",
    "kn.ref.folder": "Folder of documents", "kn.ref.folder.help": "The full path of a folder on this PC; its subfolders are read too. Empty: no reference documents.",
    "kn.ref.strategy": "How they are used", "kn.ref.strategy.help": "Automatic chooses by size. Whole at the start uses context on every turn. Searched uses little until a passage is needed. None keeps the folder but does not use it.",
    "kn.strategy.auto": "Automatic", "kn.strategy.cag": "Whole at the start (CAG)", "kn.strategy.rag": "Searched (RAG)", "kn.strategy.none": "Not used",
    "kn.ref.missing": "The folder {0} is not there: conversations start without reference documents until it is back or you change it.",
    "cp.dirs": "Skill folders", "cp.dirs.save": "Save folders", "cp.dirs.ph": "One folder per line, for example D:\\skills",
    "cp.dirs.help": "Folders with SKILL.md skills that you choose yourself (also the ones given with --skills). What is in them is listed below and is usable at once, unless you turn it off.",
    "cp.visual": "Visual analysis", "cp.visual.help": "Who looks at an image when the agent needs to: the loaded model's own vision, or a skill or MCP server found below, or no one.",
    "cp.v.builtin": "The loaded model's own vision", "cp.v.none": "None", "cp.v.on": "The loaded model can see images.",
    "cp.v.off": "The loaded model cannot see images: its vision is off. Turn it on in the model's settings (vision: dynamic) and restart the server.",
    "cp.search": "Search the entries", "cp.rescan": "Look again", "cp.rescanned": "Found {0} entries.", "cp.top": "In the agent's prompt: {0}", "cp.none": "Nothing matches.",
