    "cp.rq.title": "Install requests", "cp.rq.help": "When the agent needs a skill or an MCP server it does not have and nobody is there to ask, it looks for one online and queues its finds here, with the source, what each does and its advantages and disadvantages. Nothing is installed until you press Install on one candidate; Reject closes the request. The same choice can be put to you in the Chat.", "cp.rq.none": "No install request waits for you.", "cp.rq.need": "Needed: {0}", "cp.rq.install": "Install", "cp.rq.install.tip": "Downloads and installs this candidate without running any install script.", "cp.rq.reject": "Reject", "cp.rq.reject.tip": "Closes the request; nothing is installed.", "cp.rq.pros": "Advantages", "cp.rq.cons": "Disadvantages", "cp.rq.nocompare": "The agent has not written a comparison.", "cp.rq.status.pending": "waiting", "cp.rq.status.installed": "installed", "cp.rq.status.rejected": "rejected", "cp.rq.status.failed": "failed", "cp.rq.done": "Installed {0}.", "cp.rq.rejected": "Request rejected.", "cp.rq.score": "Score {0}/100", "cp.rq.command": "Runs: {0}", "cp.rq.keys": "Needs keys: {0}", "cp.on.title": "Search online", "cp.on.help": "When the agent lacks a capability that usually exists as an MCP server or a skill, it can look for one online and ask you which to install. What leaves this PC is the need it describes, as the search text of a request to the sources you leave on below; no file, key or conversation goes. Nothing is installed without your answer in the Chat, unless you turn on the last option. Installing runs no install script; the program starts only when the agent calls it, and any key it needs is read from your vault at that moment.",
    "cp.on.score": "The score (0 to 100) measures how much a package is used and how well it is kept up: downloads, recent and frequent releases, stars, open issues, licence, verified publisher. It does not measure safety. Read the warnings and what would run before you choose.", "cp.on.sources": "Sources asked",
    "cp.src.registry": "Official MCP registry", "cp.src.npm": "npm (package details and downloads)",
    "cp.src.pypi": "PyPI (Python package details)", "cp.src.github": "GitHub (stars, activity and licence of a repository)",
    "cp.src.skills": "Skills in GitHub repositories and in the marketplaces below", "cp.on.min": "Minimum score (0 to 100)",
    "cp.on.weights": "Weights of the score (0 to 100 each)", "cp.on.weights.help": "A fact that a source does not give is left out and the others are weighed among themselves.",
