    "cv.mtp.h": "The drafter proposes tokens that the model then checks: answers come faster and are not changed. Qwen's original layer is downloaded once (about 5 GB). A layer fine-tuned on the model's own output, which the official packs carry, is accepted more often; only that layer is read from the pack, not the whole file. None: no drafter, less memory, slower answers.",
