    "f.server.vision-hold": "Projector between images",
    "h.server.vision-hold": "Only with image input dynamic. Keep leaves the projector's weights in RAM, so the first image is quick; release frees them after each batch of images and reads them from the file again at the next one (about a second more), so the RAM and commit they hold are free in between.",
    "pr.vision.released": "Image projector ({0} GiB): not kept; it is read from the file for each batch of images and needs that much RAM and commit free for a moment while it reads one.",
