    "sub.memories": "Memories",
    "pal.set.memories": "Memories: what the assistant keeps about you",
    "me.title": "Memories",
    "me.loading": "Opening the memories...",
    "me.intro": "The assistant can keep two memories about you, learned only from what you write (never from web pages, files or tool results): a long-term one for what changes slowly, and a short-term one for what happened lately. They are encrypted on this PC with the same device key as the vault, never reach a phone, and nothing is learned or used until you switch it on here.",
    "me.long.title": "Long-term memory ({0} notes)",
    "me.long.name": "Long-term",
    "me.long.help": "Who you are, where you live, your people and companies, tastes, values, how you think and feel. It changes slowly, so a note does not expire.",
    "me.short.title": "Short-term memory ({0} notes)",
    "me.short.name": "Short-term",
    "me.short.help": "What happened lately: facts, what you looked up, what you talked about and the state of your projects. Notes are kept until you delete them, but only the recent ones go into answers.",
    "me.learn": "Learn from what I write",
    "me.learn.help.long": "A separate model call, made when the GPU is free, picks what is worth keeping and where it goes. A note it only guesses is marked as a guess.",
    "me.learn.help.short": "The same call also keeps the topics, the searches done for you and the projects you work on.",
    "me.use": "Use in answers",
    "me.use.help": "Notes are put in a request only where they match it, and each note only once in a conversation, so no tokens are spent on what does not matter.",
    "me.days.long": "Use notes seen in the last (days)",
    "me.days.help.long": "0: no limit. Older notes can still be found when you ask the assistant to look further back.",
    "me.days.short": "Use notes seen in the last (days)",
    "me.days.help.short": "Older notes are not put in answers. Ask the assistant to look further back and it searches all of them.",
    "me.w.title": "Weight of each section",
    "me.w.help": "Off: never used. Low: only a clear match, one note. Normal: notes that share words with the request, two. High: up to four, and the first two of the section at the start of a conversation. Highest: up to eight, and six at the start. A note that is only a guess needs a clear match whatever the weight.",
    "me.w.off": "Off",
    "me.w.low": "Low",
    "me.w.normal": "Normal",
    "me.w.high": "High",
    "me.w.highest": "Highest",
    "me.guessed": "Worked out by the assistant, so it starts low.",
    "me.cloud.title": "Models that are not on this PC",
    "me.cloud.risk": "RISK: your notes would leave this PC.",
    "me.cloud.help": "Your conversation may be pointed at a provider such as a cloud model. By default the notes are not put in those requests. If you allow it, the notes that match a request are sent to that provider together with it, and the provider's own rules apply to them.",
    "me.cloud.on": "Allowed: the notes are put in requests that go to other providers.",
    "me.cloud.off": "Stop sending notes away",
    "me.cloud.allow": "Allow...",
    "me.cloud.step1": "Your notes can hold your relations, work, tastes and feelings. Once a provider has received them they cannot be taken back.",
    "me.cloud.go": "I understand, go on",
    "me.cloud.step2": "Last check: send my notes to other providers when a request matches them?",
    "me.cloud.confirm": "Yes, allow it",
