    "mb.title": "Phones",
    "mb.loading": "Looking at what this PC has...",
    "mb.intro": "A phone with the Basalt app reaches this PC through Tailscale, a private network between your own devices. By default nothing is opened to the internet: the server listens only on this PC's Tailscale address (step 2 lets you change where), and every request needs the key of one phone.",
    "mb.ts.title": "1. Tailscale on this PC",
    "mb.ts.none": "Tailscale is not installed on this PC.",
    "mb.ts.install": "Install Tailscale",
    "mb.ts.install.tip": "Runs winget to install Tailscale for this PC",
    "mb.ts.installing": "Installing Tailscale... this can take a few minutes.",
    "mb.ts.install.failed": "The installation did not finish: {0}",
    "mb.ts.manual": "No winget? Install it by hand from tailscale.com/download, then come back here.",
    "mb.ts.off": "Tailscale is installed but this PC is not connected ({0}).",
    "mb.ts.connect": "Connect",
    "mb.ts.connect.tip": "Connects this PC to your Tailscale network; you may have to sign in",
    "mb.ts.signin": "Sign in to Tailscale to finish:",
    "mb.ts.open": "Open the sign-in page",
    "mb.ts.on": "Connected. Address {0}, name {1}.",
    "mb.allow.title": "2. Let phones connect",
    "mb.allow.label": "Phones may connect to this PC",
    "mb.allow.help": "A phone with its key can use the model, the conversations, the files of this PC, the routines, the plans and the rest that answers to a client with a key. What answers only to this PC itself (the wallet, the vault, the settings, the loading of models) stays on this PC.",
    "mb.allow.on": "Listening on {0}.",
    "mb.listen.label": "Listen on",
    "mb.listen.tailscale": "This PC's Tailscale address (default)",
    "mb.listen.all": "Every network interface (0.0.0.0)",
    "mb.listen.custom": "One IP address I type",
    "mb.listen.ip": "IP address to listen on",
    "mb.listen.help.tailscale": "Phones connect through your Tailscale network, which only your own devices join, and need the key of a phone. Tailscale must be connected on this PC (step 1).",
    "mb.listen.help.all": "The server answers on every network card of this PC: your home network, Wi-Fi, a VPN and Tailscale. Any device that can reach this PC's port and has a phone key can connect. The link is plain HTTP, so on a network you do not control the key can be read. Tailscale is not needed.",
    "mb.listen.help.custom": "The server answers only on the one IPv4 address you type, which must be an address of this PC, such as the one it has on your home network (192.168.1.20). The same applies to that network as for every interface. Tailscale is not needed.",
    "mb.listen.save": "Apply the address",
    "mb.listen.save.tip": "Moves the listener to this address now; a phone that was connected to the old one has to use the new address",
    "mb.listen.saved": "Saved.",
    "mb.keys.title": "3. A key for each phone",
    "mb.keys.help": "Each phone has its own key, so you can take one away without touching the others.",
    "mb.keys.none": "No phone has a key yet.",
    "mb.keys.meta": "made {0} · last used {1}",
    "mb.keys.never": "never",
    "mb.keys.revoke": "Take away",
    "mb.keys.revoke.sure": "Sure?",
    "mb.keys.revoke.tip": "The phone with this key stops working at once",
    "mb.keys.revoke.tip2": "Press again to take the key away",
    "mb.keys.name": "Name of the phone",
    "mb.keys.ph": "For example: Galaxy S25 Ultra",
    "mb.keys.make": "Make a key",
    "mb.keys.make.tip": "Makes a new key for a phone and shows its code",
    "mb.keys.show": "Show code",
    "mb.keys.show.tip": "Shows the QR code of this key again, for a phone that was reinstalled",
    "mb.keys.noshow": "made before codes could be shown again",
    "mb.keys.noend": "no end date",
    "mb.keys.ends": "ends {0}",
    "mb.keys.expired": "expired {0}",
    "mb.keys.renew": "Renew",
    "mb.keys.renew.tip": "Gives this key a new end counted from now, for the length chosen in the box below; an expired key works again",
    "mb.keys.len": "How long the key lasts",
    "mb.keys.len.tip": "After this time the phone stops working until you renew its key here",
    "mb.keys.days": "{0} days",
    "mb.keys.forever": "Never ends",
    "mb.keys.len.help.none": "A new key does not end unless you choose a length here. When a key ends the phone is refused and says so; renew it here, or take it away.",
    "mb.keys.len.help": "A key ends after {0} days unless you choose another length. When it ends the phone is refused and says so; renew it here, or take it away.",
    "mb.keys.neverwarn": "A key that never ends works until you take it away. If the phone is lost or stolen, whoever has it can use this PC from where phones connect until you notice and remove the key.",
    "mb.lim.title": "4. What a phone may start",
    "mb.lim.help": "What a conversation or routine started from a phone may do. By default the phone chooses for itself, as you would at the PC; untick the box to fix its mode and rules from here.",
    "mb.lim.chooses": "A phone chooses its own mode and permission rules",
    "mb.lim.chooses.help": "On: a phone can start a conversation in any mode, up to Auto, and give it its own rules, with the same choices you have at the PC. Off: every conversation from a phone gets the mode and the rules below, whatever the phone asks for.",
    "mb.lim.mode": "Most permissive mode for a phone",
    "mb.lim.mode.help.plan": "Phones can only start conversations that plan and change nothing until you approve the plan.",
    "mb.lim.mode.help.read_only": "Phones can start conversations that read, and ask before anything else.",
    "mb.lim.mode.help.default": "Phones can start conversations that edit the workspace and ask before running commands or anything irreversible. This is the usual choice.",
    "mb.lim.mode.help.auto": "Phones can start conversations that run commands without asking. Anyone with a phone key can then make the agent do things on this PC: use it only in a folder you can lose.",
    "mb.mode.plan": "Plan only",
    "mb.mode.read_only": "Read only",
