    "pl.f.cond.sensor.help": "A sensor resolves on the first event that satisfies \"when\" (it can use the event's text in lower case as text, source, at, and the plan's values) and writes \"set\" into the plan's values; a value that starts with = is an expression, for instance \"=text\".",
