    "pl.ev.replanfail": "The new plan could not be prepared: {0}",
    "pl.ev.offer": "A task needs you: {0}",
    "pl.ev.applied": "Change applied.",
    "pl.ev.autoapplied": "The plan was updated by itself after an event.",
    "pl.ev.autoparked": "The plan was updated by itself after an event; one part waits for you.",
    "pl.set": "Cloud filter and privacy",
    "pl.set.help": "Judging events can use TypeSafe's Jev, a cloud service. It is off until you allow it. When on, only the plan fields ticked below are sent, together with the events; people's names are replaced by labels unless you untick that option.",
    "pl.set.key.yes": "A Jev key is ready to use (from the field below or the server's environment, TYPESAFE_API_KEY).",
    "pl.badnum": "Check the numbers: the threshold, the seconds and the events per request must be numbers.",
    "pl.set.key.no": "No key yet: put it in the field below, or in the server's environment (TYPESAFE_API_KEY). The cloud filter cannot be switched on without one.",
    "pl.set.key.saved": "A Jev key is saved on this PC (in the credential store, never shown again).",
    "pl.set.key.unused": "The saved Jev key is not used yet: in the Providers tab of Models, say yes to \"Plan events (triage)\" for a provider outside this PC.",
    "pl.set.key.field": "Jev key (TypeSafe AI)",
    "pl.set.key.field.help": "Paste the key and press Save. It is kept in the credential store with the other providers' keys, never shown again and never written in a log. Leave it empty to keep the one you have.",
    "pl.set.key.remove": "Remove the saved key",
    "pl.set.threshold": "Blocker probability that wakes the model",
    "pl.set.threshold.help": "A number from 0 to 1 (0.80 is 80%). When the filter rates the chance that an event blocks the plan above it, the model is woken. Lower wakes it more often, 1 only on the other signs.",
    "pl.set.timeout": "Seconds to wait for the cloud",
    "pl.set.timeout.help": "How long one call to the cloud filter may take before the local keyword filter answers instead (default 5). Raise it on a slow connection.",
    "pl.set.chunk": "Events per cloud request",
    "pl.set.chunk.help": "A longer batch is sent in requests of this many events, and the answer is the worst of them (default 20). Lower it if the service refuses long requests.",
    "pl.set.cloud": "Allow the cloud filter",
    "pl.set.pseudo": "Replace people's names with labels, and remove e-mail addresses and phone numbers, before sending",
    "pl.set.fields": "Plan fields that may be sent",
    "pl.set.gate": "When the filter wakes the model",
    "pl.set.gate.or": "Any strong sign (default)",
    "pl.set.gate.and": "Only a strong blocker that is also serious",
    "pl.set.gate.help": "Any strong sign: a blocker probability above the threshold set below, or the whole batch affected, or the strongest event serious or critical. The other choice also needs a serious or critical impact, or the whole batch affected: the model is woken less often by events the filter rates as relevant but minor, and a serious event rated below the threshold no longer wakes it.",
    "pl.set.auto": "Apply changes automatically unless they involve people, bookings or resources I do not control",
    "pl.set.auto.help": "On by default. When an event or the Chat changes a plan, the change is applied at once and written in the history; the plan keeps going. Only the step that involves other people (a step for someone else, a call to prepare), a booking or payment already made, or a resource that cannot be changed automatically stays in Proposed changes, waiting for you; the rest of the plan goes on. Turn it off to approve every proposal yourself. Changes you ask for in a Chat that is not at the Auto level are still confirmed there.",
    "pl.set.pump": "Judge incoming events on their own",
    "pl.set.pump.help": "Events that arrive in the server's mailbox (POST /api/plans/events) or from the sources below are collected for each plan and judged when 10 have arrived or 5 minutes have passed. When the filter says wake, the local model prepares proposals; they are applied as the setting below says. On by default: it starts with the server and sleeps while nothing arrives; turn it off to stop judging events.",
    "pl.risk.pump": "Incoming events will be judged continuously, and with the cloud filter allowed they are sent to the cloud service, with names replaced if you left that on.",
    "pl.set.sources": "Sources of events (JSON)",
    "pl.set.sources.help": "Read-only. A feed: {\"kind\": \"rss\", \"url\": \"https://...\"}. A mailbox: {\"kind\": \"imap\", \"host\": \"...\", \"login_entry\": \"name of a Login in the Wallet\"}: the sender, the subject and the plain-text body are read, without marking the messages. A Telegram bot: {\"kind\": \"telegram\", \"secret_entry\": \"name of a Secret in the Wallet\", \"allowed_chat_ids\": [123]}. Passwords and tokens stay in the Wallet. This PC: {\"kind\": \"system\", \"disk_path\": \"C:\\\\\", \"min_free_gb\": 5} tells when the free space falls below the limit; {\"kind\": \"deadlines\", \"lead_days\": [7, 3, 1, 0]} tells when a plan with dates is about to start or end.",
    "pl.set.personal.help": "Sent by default, because it is what lets the filter tell that an event matters through a health condition, an allergy or the job of someone in the plan. It is personal information, and with the cloud filter on it leaves this PC (names replaced). Untick it to keep it here: the filter then judges those events less well.",
    "pl.risk.personal": "The participants' health, allergies and personal constraints will be sent to the cloud service, with names replaced if you left that on.",
    "pl.card.titolo": "Title",
    "pl.dec.exits": "Exits (at least two)",
    "pl.dec.help": "A decision takes the exits whose condition holds. Write each condition on the plan's values, for example len(invitati_confermati) >= 2; each exit becomes a step.",
    "pl.dec.exit.title": "Exit {0}: the step to take",
    "pl.dec.exit.cond": "Exit {0}: when it holds",
    "pl.dec.add": "Add an exit",
    "pl.dec.need": "A decision needs at least two exits, each with a step and a condition.",
    "pl.card.help": "The card is what incoming events are judged against: the dates, the place, who takes part and what could stop each of them.",
    "pl.card.missing": "To judge events on this plan, fill in: {0}. Without them the filter knows little about what could threaten it.",
