    "rea.title": "Reverse engineering (REA)",
    "rea.hint": "Lets the agent take apart programs, Android apps, web pages, firmware and traffic with REA, a local toolkit. Off by default. Turning it on adds REA's tools and its skill to the agent; turning it off removes exactly those.",
    "rea.more": "Programs REA can use, risk and installers",
    "rea.risk": "REA (rea-agents, MIT) runs on this PC with the Node.js shipped in the setup. On Windows its support is experimental: some tools work on Linux only. It starts the analysis programs you have installed and can open and change files you point it at: you decide what it works on, and the risk is yours. The list below shows the programs it can use; none is needed for JavaScript or Electron analysis.",
    "rea.addon": "REA add-on {0}, Node.js {1}.",
    "rea.noaddon": "The REA add-on is not part of this copy of Basalt, so the switch is unavailable.",
    "rea.mcp": "Tools registered: {0}.",
    "rea.skills": "Skill imported: {0}.",
    "rea.mcpstate.on": "yes",
    "rea.mcpstate.off": "no",
    "rea.skillstate.on": "yes",
    "rea.skillstate.off": "no",
    "rea.enabled": "REA is on: its tools and skill are now available to the agent.",
    "rea.disabled": "REA is off: its tools and skill were removed.",
    "rea.tools.h": "Programs REA can use",
    "rea.tools.hint": "Basalt looks for them on this PC. A missing one only limits what REA can analyse. Nothing is installed until you press its button; the command is shown first.",
    "rea.found": "found",
    "rea.missing": "missing",
    "rea.cmd": "Command that will run:",
    "rea.install": "Install",
    "rea.installing": "Installing... this can take several minutes.",
    "rea.manual": "No installer from here: get it from {0}, then put it where Basalt can find it (on the PATH, or in the REA tools folder in your Basalt data folder).",
    "rea.needs": "Needs: {0}.",
    "rea.all": "Install all missing ({0})",
    "rea.refresh": "Check again",
    "rea.uac": "Windows may ask you to approve an installer. Installs run with no console window; the output appears under each program.",
    "rea.done": "Finished.",
    "rea.failed": "Failed with code {0}.",
    "rea.installed": "Done. See the output under each program.",
    "rea.t.ghidra": "Ghidra",
    "rea.tw.ghidra": "Disassembler and decompiler for native programs (experimental on Windows). Needs a Java JDK.",
    "rea.t.jdk": "Java JDK",
    "rea.tw.jdk": "Full Java JDK, needed by Ghidra, JADX and Apktool.",
    "rea.t.jadx": "JADX (headless MCP)",
    "rea.tw.jadx": "Decompiles Android apps. REA wants the jadx-headless-mcp 0.7.1 JAR file.",
    "rea.t.apktool": "Apktool",
    "rea.tw.apktool": "Unpacks and rebuilds Android app resources.",
