    "rea.tw.rizin": "Open-source disassembler and analysis tool.",
    // list tools (listtools.js) and the Target Loop (target.js)
    "lt.ol": "Numbered list", "lt.ul": "Bulleted list", "lt.bar": "List tools",
    "lt.help": "makes the selected lines a list, or takes the list off. In a list Enter adds the next item, Enter on an empty item ends the list, Tab and Shift+Tab indent and outdent (Esc, then Tab, leaves the box)",
    "lt.offer": "Turn the pasted lines into a list?", "lt.keep": "Keep as pasted",
    "tg.open": "Target Loop", "tg.open.tip": "Describe a target; the agent works on it, checks it is fully met and goes on until it is",
    "tg.open.needs": "The Target Loop needs a conversation with the agent: choose Agent, not Direct, as the kind of conversation",
    "tg.title": "Target Loop", "tg.close": "Close", "tg.close.tip": "Close this window; a running target goes on",
    "tg.help": "Describe what must be true when the work is finished. The agent splits it into checkable items and tasks, does them one by one in this conversation, then a reviewer checks every item against what really happened (tool results, file changes, test output). Whatever is not met is worked on again, and nothing that is met is done twice. You can stop at any time.",
    "tg.hist": "Targets of this conversation", "tg.hist.empty": "No target yet in this conversation.",
    "tg.new": "New target", "tg.new.tip": "Write a new target",
    "tg.text.label": "Describe the target", "tg.text.ph": "For example:\n1. The site builds without errors.\n2. Every page has a title.\n3. The README explains how to run it.",
    "tg.text.help": "Long texts are fine. A numbered or bulleted list works well: each item becomes at least one item to check. Ctrl+Enter starts. Your text is also kept here if you close the window.",
    "tg.opt.title": "Options",
    "tg.opt.verify": "Commands that must succeed (one per line)", "tg.opt.verify.help": "Run in this conversation after every pass, through the normal permission gate. A command that fails keeps the loop going. For example: pytest -q",
    "tg.opt.files": "Files that must exist (one per line)", "tg.opt.files.help": "Paths inside the conversation's folder, checked after every pass.",
    "tg.opt.stall": "Passes before a different approach", "tg.opt.stall.help": "When the same items stay unmet with the same evidence for this many passes, the model proposes one different approach; if that stalls too, the loop stops with a report.",
    "tg.opt.max": "Most passes (0 is no limit)", "tg.opt.max.help": "A cap you may set; without one the loop only ends when the target is met, nothing moves any more, or you stop it.",
    "tg.opt.first": "First message", "tg.opt.first.joined": "My text and the first task in one message", "tg.opt.first.separate": "My text alone, then one message for each task",
    "tg.opt.first.help": "How the conversation starts. Joined (the default) sends your text with the first task in one message, so the model starts on the first task at once. Separate sends your text alone, as you wrote it, and then one message for each task; the model then reads the whole target before the first task, at the price of one more turn.",
    "tg.start": "Start", "tg.start.tip": "Post the target to the conversation as your message and start working on it (Ctrl+Enter)",
    "tg.stop": "Stop", "tg.stop.tip": "Stop the loop now and cancel the step the agent is on",
    "tg.resume": "Resume", "tg.resume.tip": "Go on with this target: what is met stays met, the rest is worked on",
