    "cn.line.nomodel": "Nessun modello è caricato e nel modulo non ne è indicato uno: carica un modello o scrivi il nome del modello.",
    "cn.nw.auto": "Il monitor di sicurezza era spento. Il test lo ha acceso e lo spegne di nuovo quando il test finisce.",
    "cn.nw.on": "Il monitor di sicurezza è acceso.",
    "cn.nw.off": "Il monitor di sicurezza è spento. Avviando il test si accende, e alla fine viene spento di nuovo.",
    "cn.start": "Avvia il test",
    "cn.stop": "Ferma il test",
    "cn.run.help": "Avvia esegue il test in background. Ferma lascia finire la sessione in corso e poi chiude tutto ciò che il test ha avviato. Anche chiudere Basalt lo ferma, a meno che tu abbia scelto di lasciarlo attivo.",
    "cn.started": "Il test è avviato.",
