    "ck.restored": "I file sono stati rimessi com'erano.", "ck.deleted": "Eliminato.", "ck.saved": "Salvato.",
    "ck.nochat": "Apri una conversazione per vederne i checkpoint. L'impostazione qui sopra vale per tutte le conversazioni.",
    "ck.total": "{0} checkpoint, {1} in tutto.", "ck.none": "Ancora nessun checkpoint.", "ck.failed": "Non eseguito: {0}",
    "sl.d.checkpoints": "Mostra o cambia se si fanno i checkpoint dei file",
    "sl.ck.usage": "I checkpoint sono: {0}. Usa /checkpoints on, soft, off o default.", "sl.ck.now": "Checkpoint: {0}.",
    "cs.perm": "Cosa può fare l'agente senza chiedere", "cs.perm.help": "Vale per la prossima nuova conversazione. Una regola per i comandi lascia eseguire senza chiedere quel tipo di comando; in una domanda, «Permetti sempre» ne aggiunge una per te.", "ch.answers": "Risposte", "ch.answered": "Hai risposto: {0}",
    "ch.payment.waiver": "Pagamento fatto con il tuo permesso permanente: {0} a {1} (sito: {2}); restano {3}.", "ch.payment.confirmed": "Pagamento che hai confermato: {0} a {1} (sito: {2}).",
    "ch.q.plan_approval": "Approvare questo piano e proseguire in modalità '{0}'?\n\n{1}", "ch.q.plan_outside": "L'agente ha letto contenuti esterni a questa conversazione prima di scrivere il piano.",
    "ch.q.plan_create": "Creare il piano «{0}» con {1} passi?", "ch.q.plan_mark": "Nel piano «{0}», segnare «{1}» come {2}?",
    "ch.q.plan_change": "Modificare il piano «{0}»: {1}?", "ch.q.plan_archive": "Archiviare il piano «{0}»?", "ch.q.permission": "Permettere {0} {1}?",
    "ch.retrying": "Il modello ora non risponde. Nuovo tentativo {0} tra {1} s; continua a provare finché non lo fermi.", "ch.restarting": "L'agente si è fermato e viene riavviato (tentativo {0}, tra {1} s); riprende da dove era e gli viene detto che l'ultima chiamata potrebbe essere stata eseguita.",
    "ch.pending.h": "{0}L'agente è andato avanti con altro lavoro. La tua risposta viene applicata quando la dai, anche più tardi o dal telefono.", "ch.pending.src.people": "Riguarda un'altra persona. ", "ch.pending.src.resource": "Riguarda denaro o una risorsa che non è solo tua. ", "ch.pending.src.booking": "Riguarda una prenotazione. ",
