    "ch.ask.skip.tip": "Lascia decidere all'agente col suo miglior giudizio; dirà cosa ha assunto.", "ch.ask.chat": "Rispondo nella chat", "ch.ask.chat.tip": "Chiude questa scheda: scrivi la risposta come un messaggio normale.",
