    "ch.suggest.label": "Messaggi suggeriti", "ch.suggest.tip": "Mette questo nella casella del messaggio: {0}. Non viene inviato nulla finché non premi Invia.", "ch.suggest.use": "Metti nella casella del messaggio: {0}",
    "ch.suggest.dismiss": "Nascondi i suggerimenti", "ch.intake.assumed": "Ho assunto, perché il messaggio non lo diceva: {0}.", "ch.intake.parts": "Richiesta grande, {0} parti registrate nell'elenco dei compiti: {1}.",
    "ch.intake.parked": "Lasciato a te da decidere: {0}.", "iq.title": "Domande e suggerimenti",
    "sub.inference": "Inferenza", "ps.title": "Analisi del prompt", "ps.off": "Spento", "ps.rules": "Regole", "ps.full": "Completo",
    "ps.intro": "Come viene guardato il tuo messaggio prima che il modello cominci. Le tue parole restano sempre esattamente come le hai scritte. Lo stesso interruttore è nella pagina Chat; i due mostrano sempre lo stesso valore, e una conversazione in corso usa il cambio dal messaggio successivo.",
    "ps.off.d": "Il tuo messaggio arriva al modello esattamente come l'hai scritto. Non viene controllato né cambiato nulla.",
    "ps.rules.d": "Controlli veloci, senza chiamate extra al modello. Toglie i caratteri invisibili e le righe vuote in più, scrive la data vera accanto a parole come «domani» e ricorda al modello quando hai elencato più punti. Non costa nulla.",
    "ps.full.d": "Tutto quello che fa Regole, e in più il modello legge prima la tua richiesta per vedere se manca qualcosa o se c'è un rischio. Può farti una breve domanda prima di cominciare. Aggiunge qualche secondo a ogni messaggio.",
    "ps.help": "Cosa fanno i tre stati", "ps.current": "scelto", "pal.set.prompt": "Analisi del prompt: come viene guardata prima ogni richiesta",
    "iq.defaults": "Valori predefiniti", "iq.defaults.tip": "Torna a Spento, suggerimenti attivi e dimensione predefinita.",
    "iq.sugg.title": "Suggerimenti per il messaggio successivo", "iq.sugg.on": "Suggerisci cosa scrivere dopo", "iq.sugg.help": "Dopo una risposta compaiono sotto di essa pochi suggerimenti brevi. Un clic mette solo il testo nella casella del messaggio: lo modifichi o premi Invia. Costa una breve chiamata al modello, fatta solo quando nient'altro aspetta, e mai nelle esecuzioni senza nessuno davanti.",
    "iq.size.title": "Chiamate extra e conversazioni lunghe", "iq.size": "Conversazione più lunga, in token", "iq.size.help": "Le chiamate extra (l'esame di una richiesta in modalità Completo e i suggerimenti) non si fanno in una conversazione più lunga di questo valore, perché una lunga può perdere l'inizio in cache e la risposta dopo sarebbe più lenta. Alzalo se non ti importa; abbassalo per prudenza.",
    "ch.stalled": "L'agente non rispondeva più; lo riavvio.",
    "ch.blocked.refused": "Il server ha rifiutato la richiesta", "ch.blocked.error": "La chiamata al modello è fallita", 
    "ch.blocked.crash": "L'agente ha avuto un errore",
    "ch.blocked.start_failed": "L'agente non è partito", "ch.blocked.other": "L'agente non può andare avanti da solo",
    "ch.resume": "Riprova", "ch.close": "Chiudi la conversazione", "ch.cancelled": "Fermata.", "ch.working": "L'agente sta lavorando", "ch.stopping": "Mi fermo", "ch.done": "Risposta completa",
    "ch.routed.steer": "Aggiunto a ciò che l'agente sta facendo.", "ch.routed.queue": "Può aspettare: parte quando l'agente ha finito ({0} in attesa).",
    "ch.routed.urgent": "Urgente: l'agente mette da parte il compito, fa prima questo e poi ci torna.", "ch.routed.parallel": "Il modello può farlo accanto al compito: partito ora.",
    "ch.suspended": "Il compito è messo da parte dove si trova.", "ch.resumed": "Si torna al compito messo da parte.", "ch.cleared": "Fermato, e {0} richieste in attesa tolte.",
    "ch.dropped": "Tolta dalla coda.", "ch.promote": "Fallo subito", "ch.drop": "Togli",
    "ch.ph.busy": "L'agente sta lavorando: scrivi per aggiungere o cambiare qualcosa, lo legge prima del passo successivo.",
    "ch.reasoning": "Ragionamento",
    "pv.sub.providers": "Providers", "pv.sub.qwen": "Qwen Loader",
    "pv.loaded": "Caricato:", "pv.noneLoaded": "nulla", "pv.usedBy": "usato da {0}",
    "pv.functions": "Quale provider usa ogni funzione",
    "pv.functions.help": "Ci sono solo le funzioni interne di Basalt. Gli altri programmi che usano questo server vedono sempre e solo il modello caricato. Una funzione che tratta i tuoi dati personali non può usare un provider fuori da questo PC se non dici di sì per lei.",
    "pv.council": "Consiglio",
    "pv.council.help": "Le funzioni Consiglio qui sopra sono consiglieri che discutono una domanda difficile uno dopo l'altro; il moderatore chiude il dibattito quando dice che sono d'accordo, o quando i giri finiscono. Dai a ciascuno un nome e un compito, e scegli al massimo quanti giri.",
    "pv.council.rounds": "Giri al massimo",
    "pv.council.rounds.help": "Da 1 a {0}. Un giro è ogni consigliere che parla una volta e poi il moderatore.",
    "pv.council.adviser": "Consigliere {0}",
    "pv.council.moderator": "Moderatore",
    "pv.council.name": "Nome",
    "pv.council.job": "Compito (cosa deve fare nel dibattito)",
    "pv.council.cost": "Un dibattito costa da {0} a {1} chiamate al modello; legge da {2} a {3} token e ne scrive fino a {4}. Il primo numero vale se il moderatore dichiara il consenso dopo un giro.",
    "pv.council.order": "Chi parla va uno dopo l'altro, perché ognuno risponde agli altri e un modello locale ha una sola GPU.",
    "pv.council.outside": "Fino a {0} chiamate vanno a un provider fuori da questo PC.",
    "pv.council.off": "L'agente non ha il consiglio finché almeno una funzione Consiglio qui sopra non è collegata a un provider.",
