    "pv.e.bad_council": "Queste impostazioni del consiglio non si possono usare.",
    "pv.fn": "Funzione", "pv.data": "Dati", "pv.provider": "Provider", "pv.consent": "Permesso fuori da questo PC", "pv.status": "Stato",
    "pv.data.personal": "personali", "pv.data.general": "generali", "pv.local": "Il modello caricato (questo Basalt)", "pv.local.short": "il modello caricato",
    "pv.onpc": "su questo PC", "pv.outside": "fuori da questo PC", "pv.ok": "pronto", "pv.consent.for": "Permetti a {0} di usare un provider fuori da questo PC", "pv.consent.need": "serve il tuo sì",
    "pv.providers": "Provider", "pv.providers.help": "Le chiavi stanno nel gestore credenziali di Windows, non in un file. Un provider può avere un tetto di token al giorno.",
