    "pv.f.type": "Tipo", "pv.f.name": "Nome", "pv.f.url": "Indirizzo", "pv.f.url.help": "Vuoto: si usa l'indirizzo abituale del tipo.",
    "pv.f.model": "Modello", "pv.f.key": "Chiave", "pv.f.key.help": "Solo in scrittura: va nel gestore credenziali e non si rivede più.", "pv.key.keep": "lascia vuoto per tenere la chiave salvata",
    "pv.f.profile": "Profilo di caricamento", "pv.f.profile.default": "Quello predefinito", "pv.f.profile.help": "Si usa solo quando il modello va caricato per questa funzione e il server non lo carica da sé. Un modello già caricato si usa com'è.",
    "pv.f.level": "Ragionamento", "pv.f.cap": "Token al giorno (0: nessun tetto)", "pv.f.cap.help": "Finiti, la funzione prosegue con il modello caricato.",
    "pv.f.ctx": "Finestra di contesto (token)", "pv.f.ctx.help": "La dimensione del contesto del modello, se la conosci. L'agente organizza il contesto in base a questa; vuoto: usa quella del modello caricato.", "pv.f.out": "Output massimo (token)", "pv.f.out.help": "Il massimo che una risposta può scrivere. Vuoto: quello predefinito del fornitore.",
    "pv.import.help": "Un altro programma su questo PC tiene un elenco di provider. Si può copiare qui una volta; poi i due elenchi sono separati.",
    "pv.import.copy": "Copia {0} provider da {1}", "pv.import.done": "Già copiato da {0}", "pv.import.ok": "Copiati {0} provider.", "pv.import.already": "Già copiato.",
    "pv.e.offline": "Il server non risponde.", "pv.e.bad_type": "Scegli uno dei tipi dell'elenco.", "pv.e.bad_cap": "Il tetto è un numero di token.",
    "pv.e.gone": "Quel provider non c'è più.", "pv.e.not_allowed": "Non è permesso.", "pv.e.bad_function": "Quella funzione non esiste.",
    "ch.verify.ok": "Controllato sulla richiesta: {0} punti rispettati.", "ch.verify.retry": "Non è quanto chiesto, riprovo una volta. {0}", "ch.verify.unmet": "Ancora non è quanto chiesto: {0}",
    "ch.gate.retry": "I controlli del progetto sono falliti: correggo (tentativo {0} di {1}).", "ch.gate.pass": "I controlli del progetto sono passati.", "ch.gate.stop": "I controlli del progetto non passano o non girano: il lavoro non è verificato.", "ch.ev.budget_warning": "Il limite per questa risposta è quasi esaurito.", "ch.ev.budget_grace": "Il limite è esaurito: un ultimo resoconto.", "ch.ev.stop_denied": "Un hook di arresto ha chiesto altro lavoro.",
    "pt.title": "Schemi di contesto", "pt.help": "Modi di dare forma a ciò che il modello legge nelle conversazioni della Chat con l'agente. Apri la i di ciascuno per vedere che cosa fa, in che cosa è buono e in che cosa no, e quando usarlo. Gli altri programmi che usano questo server non sono toccati.",
    "pt.what": "Che cosa fa", "pt.pros": "Vantaggi", "pt.cons": "Svantaggi", "pt.when": "Quando si usa", "pt.cache": "Cache del server",
    "pt.about": "Informazioni su {0}", "pt.strategy": "Strategia per {0}", "pt.new": "Novità: spento finché non lo accendi.", "pt.offline": "L'elenco degli schemi non si è potuto caricare.",
    "ch.branch": "Ramo da qui", "ch.branch.none": "Scrivi prima una richiesta: il ramo copia la conversazione fino all'ultima.", "ch.branch.done": "Ramo aperto. La prima conversazione non è cambiata.",
    "ch.woke": "Il planner segnala: {0}",
    "cp.title": "Capacità e analisi visiva", "cp.help": "Skill, plugin e server MCP trovati su questo PC (solo nomi, descrizioni e comandi: nessuna chiave viene letta). Ciò che si trova è subito utilizzabile, a meno che tu non lo spenga. L'agente li cerca quando gli serve uno, così non riempiono il suo prompt.",
    "kn.title": "Note di progetto, wiki e documenti di riferimento", "kn.saved": "Salvato.", "kn.save": "Salva", "kn.defaults": "Ripristina i valori delle note",
    "kn.e.offline": "Il server non ha risposto.",
    "gt.title": "Controlli prima della fine di una risposta", "gt.saved": "Salvato.", "gt.save": "Salva", "gt.defaults": "Valori predefiniti", "gt.e.offline": "Il server non ha risposto.",
    "gt.verify.title": "I controlli del progetto", "gt.verify.help": "Quando l'agente ha modificato dei file e sta per dare la risposta, questi comandi possono girare prima. Se uno fallisce, il suo output torna all'agente, che corregge la causa e risponde di nuovo. Spento finché non lo attivi.",
    "gt.commands": "Comandi di controllo", "gt.commands.help": "Un comando per riga (al massimo {0}), per esempio i test o un linter. Girano nella cartella della conversazione come ogni comando dell'agente, e metterne uno qui approva quel comando preciso: non chiede mai. Solo questo PC può cambiare l'elenco.",
    "gt.mode": "Quando girano", "gt.mode.off": "Mai", "gt.mode.unattended": "Solo quando nessuno guarda (routine, esecuzioni senza interfaccia)", "gt.mode.always": "Sempre, in ogni conversazione",
    "gt.mode.help": "Mai è il valore predefinito. Scegli quello di mezzo per far controllare da sola una esecuzione non presidiata senza rallentare le conversazioni che segui.",
    "gt.rounds": "Correzioni consentite", "gt.rounds.help": "Quante volte un controllo fallito rimanda l'agente a correggere, da 1 a 3. L'esecuzione si ferma anche quando lo stesso errore ritorna identico, o quando un comando non può girare (uno strumento mancante, nessun test trovato).",
    "gt.nocommands": "Il controllo è attivo ma non c'è nessun comando in elenco, quindi non verrà controllato nulla.",
    "gt.end.title": "Quando un limite finisce, ed errori del modello", "gt.grace": "Avvisa prima che un limite finisca e consenti un ultimo resoconto", "gt.grace.help": "Quando i passi, i token o il tempo di una risposta sono usati per nove decimi l'agente lo sa; quando finiscono ottiene ancora una risposta, senza strumenti, per dire cosa è fatto e cosa no. Disattiva per interrompere subito la risposta.",
    "gt.class": "Proposta: chiudi il turno su un errore che l'attesa non cura", "gt.class.help": "In attesa della decisione del proprietario, spento di default. Oggi ogni chiamata fallita al modello è ritentata senza fine. Con questa attiva, una richiesta che il server del modello rifiuterà sempre (richiesta malformata, chiave rifiutata) chiude il turno e mostra l'errore; server occupati, in caricamento, con limite di richieste o irraggiungibili si aspettano ancora.",
    "cd.role": "Ruolo",
    "cd.role.tip": "A cosa serve l'agente in questa conversazione. Decide quali strumenti può usare e le regole di lavoro che riceve. Puoi cambiarlo quando vuoi; la conversazione continua.",
    "cd.role.build": "Developer",
    "cd.role.build.d": "Developer: legge, cerca, modifica i file ed esegue i controlli del progetto. Il ruolo di solito per cambiare il codice.",
    "cd.role.plan": "Pianifica",
    "cd.role.plan.d": "Pianifica: legge e fa domande, e scrive solo un piano in .basalt/plans. Non cambia altro e non esegue nulla.",
    "cd.role.ask": "Domanda",
    "cd.role.ask.d": "Domanda: risponde a domande sul progetto. Legge e cerca; non può cambiare file né eseguire comandi.",
    "cd.role.debug": "Debug",
    "cd.role.debug.d": "Debug: come Developer, ma trova e conferma la causa di un difetto prima di correggerlo.",
    "cd.role.orchestrate": "Orchestra",
    "cd.role.orchestrate.d": "Orchestra: divide il lavoro tra sotto-agenti e controlla ciò che riportano. Non modifica file né esegue comandi da sé.",
    "cd.role.general": "Generale",
    "cd.role.general.d": "Generale: nessun limite agli strumenti, come nella Chat. Serve per navigare, scrivere documenti o tutto ciò che non è codice.",
    "cd.role.now": "Il ruolo ora è {0}.",
    "cd.checks.now": "Controlli approvati aggiornati: {0} girano senza chiedere.",
    "cd.card.title": "Controlli del progetto",
    "cd.card.open": "Esamina",
    "cd.card.close": "Chiudi",
    "cd.card.tip": "I test, il linter e la build che questa cartella sembra avere. Nulla gira finché non accetti un comando.",
    "cd.card.help": "Questi comandi sono stati letti dai file della cartella; nessuno è stato eseguito. Accetta quelli di cui ti fidi: un comando accettato gira senza chiedere, scritto esattamente così. Se il progetto cambia ciò che un comando fa, te lo richiede.",
    "cd.card.none": "I controlli di questa cartella non sono ancora mostrati.",
