    "cd.e.offline": "Il server non ha risposto.",
    "cd.empty": "Questa cartella è vuota. Di solito conviene pianificare prima.",
    "cd.empty.btn": "Usa il ruolo Pianifica",
    "cd.go": "Continua in {0}",
    "cd.go.tip": "Passa al ruolo Developer e chiede all'agente di realizzare il piano appena fatto.",
    "cd.go.text": "Procedi e realizza il piano.",
    "cd.bug": "Sembra un difetto: passa a {0}",
    "cd.bug.tip": "Il ruolo Debug trova e conferma la causa prima di correggere qualsiasi cosa. Non cambia nulla se non premi questo.",
    "cx.title": "Lavori lunghi: riassunto dei passi vecchi", "cx.saved": "Salvato.", "cx.save": "Salva", "cx.defaults": "Valori predefiniti", "cx.e.offline": "Il server non ha risposto.",
    "cx.on": "Riassumi i passi più vecchi quando il contesto è quasi pieno",
    "cx.on.help": "Mentre l'agente svolge molti passi in una sola richiesta, la sua conversazione cresce. I risultati vecchi degli strumenti sono prima sostituiti da note brevi (nulla si perde: il testo intero è salvato). Se la conversazione è ancora vicina al limite, i passi più vecchi diventano un riassunto che il modello scrive con una chiamata a parte, e i passi più recenti restano come erano. Il prompt di sistema e l'elenco degli strumenti non cambiano mai. Spento: resta solo la mascheratura dei risultati vecchi, e una richiesta che supera la finestra può fallire.",
    "cx.threshold": "Parti a (% del budget del prompt)",
    "cx.threshold.help": "La quota di spazio che la conversazione può usare prima che i passi vecchi siano riassunti, da 50 a 98. Non parte mai prima che i risultati vecchi siano mascherati (la soglia della Chat). Più bassa parte prima e lascia più spazio libero; più alta tiene più dettaglio e lascia meno margine. Il valore normale è 85.",
    "cx.cost": "Ogni riassunto è una chiamata in più al modello, e dopo di esso il server rilegge la conversazione accorciata; la sua entità è mostrata nella chat e da /context.",
    "ch.ev.compaction": "I passi precedenti sono stati riassunti: da {0} a {1} token; il server ne rilegge circa {2}.", "ch.ev.compaction_cache": "Dopo il riassunto il server ha preso {1} token su {0} dalla sua cache.",
    "sl.r.cx.off": "I riassunti dei passi vecchi sono spenti.", "sl.r.cx.on": "I riassunti partono al {0}% del budget; fatti finora: {1}.",
    "sl.r.cx.last": "L'ultimo: da {0} a {1} token, {2} messaggi sostituiti, scritto da {3}.", "sl.r.cx.by.model": "il modello", "sl.r.cx.by.extract": "un estratto semplice",
    "sl.r.cx.prefix": "Inizio rimasto com'era: {0} token; riletti dal server: {1}.", "sl.r.cx.observed": "Cache del server dopo di esso: {0} su {1} token.", "sl.r.cx.reread": "Non nel riassunto, da rileggere: {0}.",
    "kn.notes.title": "Note di progetto aggiunte a una richiesta",
    "kn.notes.help": "L'agente tiene brevi note su un progetto (ciò che ricorda). A ogni richiesta si aggiungono solo le note che hanno abbastanza in comune con ciò che hai scritto, dopo il tuo messaggio e come dati. Le conversazioni che lavorano in copie dello stesso repository condividono le stesse note.",
    "kn.score": "Punti che una nota deve ottenere", "kn.score.help": "Ogni parola della tua richiesta che una nota ha anch'essa vale fino a 1 punto (meno se molte note la hanno); una parola specifica come sm_120 o e-mail vale fino a 2. Le parole comuni (il, di, the, and) non contano mai. Una nota è aggiunta quando i suoi punti raggiungono questo numero; una richiesta breve, fino a tre parole, è servita anche da una nota che le ha tutte. Più alto: meno note, più precise. 0: le migliori corrispondenze qualunque cosa abbiano in comune.",
    "kn.count": "Massimo di note per richiesta", "kn.count.help": "A una richiesta si aggiungono al più tante note. 0: nessuna da sola (l'agente può comunque cercarle).",
    "kn.budget": "Massimo di token per le note", "kn.budget.help": "Le note aggiunte a una richiesta non occupano mai più di tanti token del contesto. Una nota che non ci sta è lasciata fuori.",
    "kn.wiki.title": "Wiki (wikibridge)", "kn.wiki.help": "Una wiki di conoscenza che gira su questo PC o sulla tua rete. Se è attiva, la Chat, l'Agente e i passi di piano che interrogano la wiki possono cercarvi e leggerne le pagine. Ciò che restituisce è trattato come dati, non come ordini.",
    "kn.wiki.on": "Offri la wiki alla Chat e all'Agente", "kn.wiki.url": "Indirizzo del wikibridge", "kn.wiki.url.help": "Dove risponde il servizio, per esempio http://127.0.0.1:8775. Vuoto: l'indirizzo in BASALT_WIKIBRIDGE_URL, altrimenti quello. Se il servizio chiede una chiave, imposta BASALT_WIKIBRIDGE_KEY su questo PC.",
    "kn.wiki.project": "Progetto della wiki", "kn.wiki.project.help": "Il progetto (slug) usato quando una richiesta non ne indica uno. Vuoto: il primo che la wiki elenca.",
    "kn.wiki.check": "Verifica la connessione", "kn.wiki.checking": "Interrogo la wiki...", "kn.wiki.ok": "La wiki risponde a {0} ({1} progetti).", "kn.wiki.bad": "La wiki non ha risposto a {0}: {1}",
    "kn.ref.title": "Documenti di riferimento (RAG e CAG)", "kn.ref.help": "Una cartella di documenti .md e .txt che l'agente può usare. Gli insiemi piccoli sono messi interi all'inizio della conversazione (CAG, veloce ma riempie il contesto); quelli grandi sono cercati e arrivano solo i passaggi che corrispondono (RAG). Valgono per le conversazioni che iniziano dopo il salvataggio.",
    "kn.ref.folder": "Cartella dei documenti", "kn.ref.folder.help": "Il percorso completo di una cartella su questo PC; si leggono anche le sottocartelle. Vuoto: nessun documento di riferimento.",
    "kn.ref.strategy": "Come si usano", "kn.ref.strategy.help": "Automatico sceglie in base alla dimensione. Interi all'inizio occupano contesto a ogni turno. Cercati usano poco finché non serve un passaggio. Nessuno tiene la cartella ma non la usa.",
    "kn.strategy.auto": "Automatico", "kn.strategy.cag": "Interi all'inizio (CAG)", "kn.strategy.rag": "Cercati (RAG)", "kn.strategy.none": "Non usati",
    "kn.ref.missing": "La cartella {0} non c'è: le conversazioni partono senza documenti di riferimento finché non torna o la cambi.",
    "cp.dirs": "Cartelle di skill", "cp.dirs.save": "Salva le cartelle", "cp.dirs.ph": "Una cartella per riga, per esempio D:\\skills",
    "cp.dirs.help": "Cartelle con skill SKILL.md scelte da te (anche quelle date con --skills). Ciò che contengono compare qui sotto ed è subito utilizzabile, a meno che tu non lo spenga.",
    "cp.visual": "Analisi visiva", "cp.visual.help": "Chi guarda un'immagine quando l'agente deve: la visione del modello caricato, oppure una skill o un server MCP tra quelli sotto, oppure nessuno.",
    "cp.v.builtin": "La visione del modello caricato", "cp.v.none": "Nessuna", "cp.v.on": "Il modello caricato vede le immagini.",
    "cp.v.off": "Il modello caricato non vede le immagini: la sua visione è spenta. Accendila nelle impostazioni del modello (vision: dynamic) e riavvia il server.",
    "cp.search": "Cerca tra le voci", "cp.rescan": "Rileva di nuovo", "cp.rescanned": "Trovate {0} voci.", "cp.top": "Nel prompt dell'agente: {0}", "cp.none": "Nessuna voce corrisponde.",
    "cp.review": "Vedi il testo", "cp.review.help": "Questo è ciò che l'agente usa. Se è una skill, l'agente la legge come istruzioni; se è un server, viene avviato con questo comando.",
    "cp.cancel": "Annulla", "cp.close": "Chiudi", "cp.turnoff": "Spegni", "cp.turnon": "Accendi",
