    "cp.rq.title": "Richieste di installazione", "cp.rq.help": "Quando all'agente serve una skill o un server MCP che non ha e non c'è nessuno a cui chiedere, li cerca online e mette qui ciò che trova, con la fonte, che cosa fa ciascuno, vantaggi e svantaggi. Nulla viene installato finché non premi Installa su un candidato; Rifiuta chiude la richiesta. La stessa scelta può esserti posta anche nella Chat.", "cp.rq.none": "Nessuna richiesta di installazione ti aspetta.", "cp.rq.need": "Serve: {0}", "cp.rq.install": "Installa", "cp.rq.install.tip": "Scarica e installa questo candidato senza eseguire alcuno script di installazione.", "cp.rq.reject": "Rifiuta", "cp.rq.reject.tip": "Chiude la richiesta; non viene installato nulla.", "cp.rq.pros": "Vantaggi", "cp.rq.cons": "Svantaggi", "cp.rq.nocompare": "L'agente non ha scritto un confronto.", "cp.rq.status.pending": "in attesa", "cp.rq.status.installed": "installata", "cp.rq.status.rejected": "rifiutata", "cp.rq.status.failed": "non riuscita", "cp.rq.done": "Installata {0}.", "cp.rq.rejected": "Richiesta rifiutata.", "cp.rq.score": "Punteggio {0}/100", "cp.rq.command": "Esegue: {0}", "cp.rq.keys": "Servono chiavi: {0}", "cp.on.title": "Cerca online", "cp.on.help": "Quando all'agente manca una capacità che di solito esiste come server MCP o come skill, può cercarla online e chiederti quale installare. Fuori da questo PC esce il bisogno che descrive, come testo di ricerca di una richiesta alle fonti che lasci attive qui sotto; nessun file, chiave o conversazione. Nulla viene installato senza una tua risposta nella Chat, a meno che tu non attivi l'ultima opzione. L'installazione non esegue alcuno script di installazione; il programma parte solo quando l'agente lo chiama, e l'eventuale chiave che gli serve viene letta dal tuo vault in quel momento.",
    "cp.on.score": "Il punteggio (da 0 a 100) misura quanto un pacchetto è usato e quanto è curato: download, rilasci recenti e frequenti, stelle, issue aperte, licenza, ente verificato. Non misura la sicurezza. Leggi gli avvisi e che cosa verrebbe eseguito prima di scegliere.", "cp.on.sources": "Fonti interrogate",
