    "br.nodes.title": "Messaggi come nodi",
    "br.nodes.help": "Ogni messaggio è un nodo che segue un altro e non viene mai modificato. I rami condividono i nodi della loro partenza, quindi un ramo non copia nulla. Un tratto sono i messaggi tra due biforcazioni. Prima di cambiare conversazione vedi quanto costa al modello.",
