    "br.merge.title": "Unisci e sintetizza",
    "br.merge.help": "Il modello legge cosa hanno fatto due conversazioni dopo il punto in cui si sono separate e scrive una sola sintesi. Nasce una nuova conversazione dalla prima, che finisce con quella sintesi; le due non cambiano.",
