    "ch.back": "Torna qui", "ch.back.sure": "Premi ancora: ciò che è venuto dopo si toglie", "ch.back.n": "Torna a subito dopo: {0}", "ch.back.busy": "Aspetta che l'agente finisca, o fermalo, prima di tornare indietro.", "ch.back.done": "Tornato lì. I file che l'agente ha cambiato non sono toccati: annullali dal pannello delle modifiche.",
    "pl.mermaid": "Copia come diagramma Mermaid", "pl.mermaid.help": "Il piano come testo per un documento o una pagina che disegna diagrammi (visualizzatori Markdown, wiki).", "pl.mermaid.copied": "Copiato.", "pl.mermaid.manual": "Seleziona il testo e copialo.", "pl.mermaid.fail": "Non si è potuto fare il diagramma.",
    "cs.showreasoning": "Mostra il ragionamento", "cs.showreasoning.help": "Mostra il ragionamento del modello in un riquadro sopra la risposta: aperto mentre ragiona, chiuso quando ha finito, alto 20 righe.",
    "cs.budget": "Budget di ragionamento (token)", "cs.budget.help": "Il ragionamento si chiude dopo questi token; vuoto = nessun limite.",
    "cs.max_tokens": "Token massimi in uscita", "cs.max_tokens.help": "Vuoto = tutto il contesto che resta.",
    "cs.max_answer_tokens": "Token massimi della risposta", "cs.max_answer_tokens.help": "Il massimo che il testo della risposta può occupare, senza contare il ragionamento; poi la risposta finisce come tagliata, con il pulsante Continua. Vuoto = nessun limite a parte.",
    "cs.max_turns": "Passi massimi per risposta", "cs.max_turns.bad": "-1 per nessun limite, oppure 1 o più",
    "cs.max_turns.help": "Quanti passi può fare l'agente per rispondere a un messaggio; un passo è una chiamata al modello, di solito seguita da chiamate a strumenti. -1 o vuoto significa nessun limite, che è l'impostazione predefinita: si ferma quando ha risposto, finisce il budget o continua a ripetersi. Una modifica arriva alla conversazione aperta dalla sua prossima esecuzione.",
    "cs.live": "Questa conversazione: passi per risposta {0}; spinta sulla fine del turno {1}.", "cs.live.none": "nessun limite",
    "ch.settings.steps": "I passi per risposta ora sono {0}.", "ch.settings.bias": "La spinta sulla fine del turno ora è {0}.",
    "ch.stop.max_turns": "Fermato dopo {0} passi senza aver finito.", "ch.stop.max_turns.h": "Continua invia un altro messaggio così l'agente prosegue da dove si è fermato; il limite si imposta nelle impostazioni della chat.",
    "ch.continue": "Continua", "ch.continue.text": "Continua.",
    "ch.stop.length": "Il limite di uscita ha chiuso questa risposta.", "ch.stop.length.h": "Continua invia un altro messaggio così l'agente prosegue esattamente da dove si è fermato.",
