    "cs.policy.stop": "Ferma al limite", "cs.policy.stop.help": "Non si toglie nulla; un messaggio che non ci sta viene rifiutato.",
    "cs.context.help": "Questi tre sono il modo di base per restare nel contesto e valgono in ogni modalità. Gli schemi qui sotto lo affinano (mascherano i vecchi risultati degli strumenti, tolgono i turni meno pertinenti, scrivono riassunti strutturati o incrementali) e valgono in Con strumenti e Solo domanda.",
    "cs.policy.rolling": "Finestra scorrevole", "cs.policy.rolling.help": "Si lasciano fuori i turni più vecchi; restano il prompt di sistema, il primo messaggio e i turni più recenti.",
    "cs.policy.compact": "Compatta", "cs.policy.compact.help": "Alla soglia il modello riassume i turni di mezzo in un solo messaggio; inizio e turni recenti restano identici. Se il riassunto non si riesce a scrivere, si lasciano fuori i turni più vecchi e la chat lo dice.",
