    "cp.actions.help": "Su ogni voce: «Vedi il testo» mostra ciò che l'agente legge o esegue; «Spegni» la nasconde all'agente finché non la riaccendi; «Accedi» e «Esci» servono per i server remoti; il menu sposta la voce nell'albero.",
