    "pl.set.cloud.help": "Manda al filtro nel cloud i campi del piano spuntati qui sotto e gli eventi. Salute, allergie e vincoli personali dei partecipanti restano a casa se non li spunti. Spento di base; serve una chiave sul server.",
    "pl.set.pseudo.help": "Consigliato. Sostituisce i nomi delle persone del piano e dei mittenti di mail e messaggi; non può trovare un nome scritto dentro il testo di un messaggio o l'oggetto di una mail. Senza spunta, nomi veri, indirizzi e-mail e numeri di telefono arrivano al servizio cloud.",
