    "f.engine.relaxed-drafting": "Bozze rilassate",
    "h.engine.relaxed-drafting": "Risposte campionate più veloci al prezzo di un po' di esattezza: una bozza a cui il modello dà almeno questa probabilità viene tenuta anche se la sua estrazione sarebbe stata un altro token. Spento, l'output è esattamente quello della decodifica normale. A temperatura 0, nelle risposte JSON, con il logit bias e dentro le chiamate agli strumenti resta comunque esatto. Misurato a 400 W: circa +5% / +10% con 0,5 e fino a +20% con 0,2 (temperatura 1,0).",
    "o.engine.relaxed-drafting.0.5": "0,5: la minima differenza dal campionamento esatto, il guadagno più piccolo",
