    "tr.title": "Tracce delle sessioni",
    "tr.intro": "Una traccia è la registrazione salvata di una conversazione di Chat o Agente: che cosa hai chiesto, che cosa ha risposto il modello, quali strumenti ha chiamato e che cosa è stato deciso su ogni chiamata. La riproduzione rifà la conversazione con le risposte registrate e strumenti finti: non viene chiamato nessun modello e nulla sul tuo disco cambia.",
