    "pal.set.memories": "Memorie: ciò che l'assistente tiene di te",
    "me.title": "Memorie",
    "me.loading": "Apro le memorie...",
    "me.intro": "L'assistente può tenere due memorie su di te, imparate solo da ciò che scrivi tu (mai da pagine web, file o risultati di strumenti): una a lungo termine per ciò che cambia lentamente e una a breve termine per ciò che è successo da poco. Sono cifrate su questo PC con la stessa chiave del portafoglio, non raggiungono mai un telefono e nulla viene imparato o usato finché non lo accendi qui.",
    "me.long.title": "Memoria a lungo termine ({0} note)",
    "me.long.name": "Lungo termine",
    "me.long.help": "Chi sei, dove vivi, le tue persone e le tue aziende, gusti, valori, come pensi e come ti senti. Cambia lentamente, quindi una nota non scade.",
    "me.short.title": "Memoria a breve termine ({0} note)",
    "me.short.name": "Breve termine",
    "me.short.help": "Ciò che è successo da poco: fatti, ricerche, argomenti di cui hai parlato e stato dei progetti. Le note restano finché non le cancelli, ma nelle risposte entrano solo le recenti.",
    "me.learn": "Impara da ciò che scrivo",
    "me.learn.help.long": "Una chiamata separata al modello, fatta quando la GPU è libera, sceglie cosa vale la pena tenere e dove metterlo. Una nota solo intuita è segnata come tale.",
    "me.learn.help.short": "La stessa chiamata tiene anche gli argomenti, le ricerche fatte per te e i progetti su cui lavori.",
    "me.use": "Usa nelle risposte",
    "me.use.help": "Le note entrano in una richiesta solo dove le corrispondono e ognuna una sola volta in una conversazione, così non si spendono token per ciò che non serve.",
    "me.days.long": "Usa le note viste negli ultimi (giorni)",
    "me.days.help.long": "0: nessun limite. Le note più vecchie si trovano comunque quando chiedi all'assistente di guardare più indietro.",
    "me.days.short": "Usa le note viste negli ultimi (giorni)",
    "me.days.help.short": "Le note più vecchie non entrano nelle risposte. Chiedi all'assistente di guardare più indietro e cerca in tutte.",
    "me.w.title": "Peso di ogni sezione",
    "me.w.help": "Spento: mai usata. Basso: solo una corrispondenza chiara, una nota. Normale: le note che hanno parole in comune con la richiesta, due. Alto: fino a quattro, e le prime due della sezione all'inizio di una conversazione. Altissimo: fino a otto, e sei all'inizio. Una nota solo intuita richiede una corrispondenza chiara qualunque sia il peso.",
    "me.w.off": "Spento",
    "me.w.low": "Basso",
    "me.w.normal": "Normale",
    "me.w.high": "Alto",
    "me.w.highest": "Altissimo",
    "me.guessed": "Dedotta dall'assistente, quindi parte bassa.",
    "me.cloud.title": "Modelli che non sono su questo PC",
    "me.cloud.risk": "RISCHIO: le tue note uscirebbero da questo PC.",
    "me.cloud.help": "La tua conversazione può essere diretta a un fornitore, per esempio un modello in cloud. Di norma le note non entrano in quelle richieste. Se lo permetti, le note che corrispondono a una richiesta partono verso quel fornitore insieme ad essa e valgono le sue regole.",
    "me.cloud.on": "Permesso: le note entrano nelle richieste che vanno ad altri fornitori.",
    "me.cloud.off": "Smetti di mandare le note fuori",
    "me.cloud.allow": "Permetti...",
    "me.cloud.step1": "Le tue note possono contenere relazioni, lavoro, gusti e sentimenti. Quando un fornitore le ha ricevute non si possono riprendere.",
    "me.cloud.go": "Ho capito, vai avanti",
    "me.cloud.step2": "Ultima verifica: mandare le mie note ad altri fornitori quando una richiesta le riguarda?",
    "me.cloud.confirm": "Sì, permettilo",
