    "mb.title": "Telefoni",
    "mb.loading": "Guardo cosa c'è su questo PC...",
    "mb.intro": "Un telefono con l'app Basalt raggiunge questo PC tramite Tailscale, una rete privata tra i tuoi dispositivi. Di norma non si apre nulla verso internet: il server ascolta solo sull'indirizzo Tailscale di questo PC (al passo 2 puoi cambiare dove) e ogni richiesta richiede la chiave di un telefono.",
    "mb.ts.title": "1. Tailscale su questo PC",
    "mb.ts.none": "Tailscale non è installato su questo PC.",
    "mb.ts.install": "Installa Tailscale",
    "mb.ts.install.tip": "Esegue winget per installare Tailscale su questo PC",
    "mb.ts.installing": "Installo Tailscale... può volerci qualche minuto.",
    "mb.ts.install.failed": "L'installazione non è finita: {0}",
    "mb.ts.manual": "Niente winget? Installalo a mano da tailscale.com/download, poi torna qui.",
    "mb.ts.off": "Tailscale è installato ma questo PC non è collegato ({0}).",
    "mb.ts.connect": "Collega",
    "mb.ts.connect.tip": "Collega questo PC alla tua rete Tailscale; potrebbe servire accedere",
    "mb.ts.signin": "Accedi a Tailscale per finire:",
    "mb.ts.open": "Apri la pagina di accesso",
    "mb.ts.on": "Collegato. Indirizzo {0}, nome {1}.",
    "mb.allow.title": "2. Lascia collegare i telefoni",
    "mb.allow.label": "I telefoni possono collegarsi a questo PC",
    "mb.allow.help": "Un telefono con la sua chiave può usare il modello, le conversazioni, i file di questo PC, le routine, i piani e il resto che risponde a un client con una chiave. Ciò che risponde solo a questo PC stesso (portafoglio, cassaforte, impostazioni, caricamento dei modelli) resta su questo PC.",
    "mb.allow.on": "In ascolto su {0}.",
    "mb.listen.label": "Ascolta su",
    "mb.listen.tailscale": "L'indirizzo Tailscale di questo PC (predefinito)",
    "mb.listen.all": "Tutte le interfacce di rete (0.0.0.0)",
    "mb.listen.custom": "Un indirizzo IP che scrivo io",
    "mb.listen.ip": "Indirizzo IP su cui ascoltare",
    "mb.listen.help.tailscale": "I telefoni si collegano tramite la tua rete Tailscale, a cui partecipano solo i tuoi dispositivi, e hanno bisogno della chiave di un telefono. Tailscale deve essere collegato su questo PC (passo 1).",
    "mb.listen.help.all": "Il server risponde su ogni scheda di rete di questo PC: la rete di casa, il Wi-Fi, una VPN e Tailscale. Qualunque dispositivo che raggiunga la porta di questo PC e abbia la chiave di un telefono può collegarsi. Il collegamento è HTTP semplice, quindi su una rete che non controlli la chiave può essere letta. Tailscale non serve.",
    "mb.listen.help.custom": "Il server risponde solo sul singolo indirizzo IPv4 che scrivi, che deve essere un indirizzo di questo PC, per esempio quello che ha sulla rete di casa (192.168.1.20). Per quella rete vale quanto detto per tutte le interfacce. Tailscale non serve.",
    "mb.listen.save": "Applica l'indirizzo",
    "mb.listen.save.tip": "Sposta subito l'ascolto su questo indirizzo; un telefono collegato al vecchio indirizzo deve usare il nuovo",
    "mb.listen.saved": "Salvato.",
    "mb.keys.title": "3. Una chiave per ogni telefono",
    "mb.keys.help": "Ogni telefono ha la sua chiave, così puoi toglierne una senza toccare le altre.",
    "mb.keys.none": "Nessun telefono ha ancora una chiave.",
    "mb.keys.meta": "creata {0} · ultimo uso {1}",
    "mb.keys.never": "mai",
    "mb.keys.revoke": "Togli",
    "mb.keys.revoke.sure": "Sicuro?",
    "mb.keys.revoke.tip": "Il telefono con questa chiave smette di funzionare subito",
    "mb.keys.revoke.tip2": "Premi ancora per togliere la chiave",
    "mb.keys.name": "Nome del telefono",
    "mb.keys.ph": "Per esempio: Galaxy S25 Ultra",
    "mb.keys.make": "Crea una chiave",
    "mb.keys.make.tip": "Crea una nuova chiave per un telefono e ne mostra il codice",
    "mb.keys.show": "Mostra il codice",
    "mb.keys.show.tip": "Mostra di nuovo il codice QR di questa chiave, per un telefono su cui l'app è stata reinstallata",
    "mb.keys.noshow": "creata prima che i codici si potessero rivedere",
    "mb.keys.noend": "senza scadenza",
    "mb.keys.ends": "scade il {0}",
    "mb.keys.expired": "scaduta il {0}",
    "mb.keys.renew": "Rinnova",
    "mb.keys.renew.tip": "Dà a questa chiave una nuova scadenza a partire da adesso, della durata scelta nel riquadro qui sotto; una chiave scaduta torna a funzionare",
    "mb.keys.len": "Quanto dura la chiave",
    "mb.keys.len.tip": "Passato questo tempo il telefono smette di funzionare finché non rinnovi qui la sua chiave",
    "mb.keys.days": "{0} giorni",
    "mb.keys.forever": "Non scade mai",
    "mb.keys.len.help.none": "Una chiave nuova non scade, a meno che tu scelga qui una durata. Quando una chiave scade il telefono viene rifiutato e lo dice; rinnovala qui, oppure toglila.",
    "mb.keys.len.help": "Una chiave scade dopo {0} giorni, a meno che tu scelga un'altra durata. Quando scade il telefono viene rifiutato e lo dice; rinnovala qui, oppure toglila.",
    "mb.keys.neverwarn": "Una chiave che non scade funziona finché non la togli. Se il telefono viene perso o rubato, chi lo ha può usare questo PC da dove i telefoni si collegano finché non te ne accorgi e togli la chiave.",
    "mb.lim.title": "4. Cosa può avviare un telefono",
    "mb.lim.help": "Cosa può fare una conversazione o una routine avviata da un telefono. Di norma il telefono sceglie da solo, come faresti al PC; togli la spunta per fissare da qui modalità e regole.",
    "mb.lim.chooses": "Il telefono sceglie da solo modalità e regole di permesso",
    "mb.lim.chooses.help": "Attivo: un telefono può avviare una conversazione in qualunque modalità, anche Auto, e darle regole sue, con le stesse scelte che hai al PC. Spento: ogni conversazione da telefono riceve la modalità e le regole qui sotto, qualunque cosa chieda il telefono.",
    "mb.lim.mode": "Modalità più permissiva per un telefono",
    "mb.lim.mode.help.plan": "I telefoni possono avviare solo conversazioni che fanno un piano e non cambiano nulla finché non lo approvi.",
    "mb.lim.mode.help.read_only": "I telefoni possono avviare conversazioni che leggono e chiedono prima di qualunque altra cosa.",
    "mb.lim.mode.help.default": "I telefoni possono avviare conversazioni che modificano la cartella di lavoro e chiedono prima di eseguire comandi o azioni irreversibili. È la scelta normale.",
    "mb.lim.mode.help.auto": "I telefoni possono avviare conversazioni che eseguono comandi senza chiedere. Chi ha una chiave di telefono può allora far fare cose all'agente su questo PC: usala solo in una cartella che puoi perdere.",
    "mb.mode.plan": "Solo piano",
    "mb.mode.read_only": "Sola lettura",
    "mb.mode.default": "Chiedi prima di eseguire (predefinita)",
    "mb.mode.auto": "Automatica",
    "mb.lim.rules": "Regole di permesso per le conversazioni avviate da un telefono",
    "mb.lim.rules.help": "Una regola per riga, per esempio shell_command:pytest *. Vuoto significa che ogni comando e strumento chiede. Prendono il posto di quanto invia il telefono.",
    "mb.lim.save": "Salva i limiti",
    "mb.lim.save.tip": "Vale per le conversazioni e le routine avviate da un telefono da adesso in poi",
    "mb.lim.saved": "Salvato.",
    "mb.fresh.title": "Chiave per {0}",
    "mb.fresh.once": "La vedi solo adesso. Inquadra il codice con l'app, oppure copia la chiave; se la perdi, toglila e creane un'altra.",
    "mb.fresh.again": "Inquadra il codice con l'app, oppure copia la chiave. Puoi rivedere questo codice dall'elenco, per esempio dopo aver reinstallato l'app; la chiave resta cifrata su questo PC.",
    "mb.fresh.address": "Indirizzo per l'app: {0}",
