    "mb.fresh.qrhelp": "Nell'app: Impostazioni, poi Inquadra il codice.",
    "mb.fresh.done": "Ce l'ho, chiudi",
    "mb.phone.help": "Sul telefono: installa Tailscale dal Play Store e accedi con lo stesso account di qui, poi installa l'app Basalt e inquadra il codice, oppure scrivi indirizzo e chiave nelle sue impostazioni.",
    "cj.kind": "Cosa esegue",
