    "cj.minutes.help": "Un numero intero di minuti da 1. Quando una esecuzione lo raggiunge viene fermata e registrata come troppo lunga. Lascia vuoto per nessun limite di tempo.",
    "cj.auto.help": "Un job gira sempre in Automatica: fa quello che serve senza chiedere, nella cartella che hai scelto, che tu sia al PC o no. Job diversi girano insieme; lo stesso job non gira mai due volte insieme. Un orario fisso perso perché il PC era spento viene eseguito una volta, in ritardo, all'avvio dell'app.",
    "cj.pending.title": "Ti aspettano",
