    "cj.prompt": "Cosa fa l'agente ogni volta",
    "cj.prompt.help": "Scrivilo come un'istruzione. Il job parte da solo, in Automatica, e va avanti anche se non ci sei: non aspetta una risposta. Solo una richiesta che serve a te (un'altra persona, una prenotazione, qualcosa che non controlla) finisce nell'elenco delle richieste che ti aspettano.",
