    "cj.yield.never": "mai",
    "cj.yield.help": "Se una tua conversazione è al lavoro mentre questo compito gira, il compito viene fermato quando la conversazione lavora da questi secondi (0: subito), così non aspetti il modello. Non riparte da solo: ci pensa la sua prossima ora. Lascia vuoto per non fermarlo mai.",
