    "pl.f.cond.sensor.help": "Un sensore si risolve al primo evento che soddisfa \"when\" (può usare il testo dell'evento in minuscolo come text, source, at e i valori del piano) e scrive \"set\" nei valori del piano; un valore che comincia con = è un'espressione, per esempio \"=text\".",
    "pl.h.sensor": "sensore",
    "pl.moved": "{0} spostato in {1}, {2}",
    "pl.tele": "Filtro dall'avvio del server: {0} valutazioni ({1} dal cloud, {2} dal filtro locale, {3} in cui il cloud ha fallito e ha risposto il filtro locale), {4} token, {5} hanno svegliato il modello.",
