    "pl.t.local": "nulla è uscito da questo PC",
    "pl.t.detail": "Probabilità di blocco {0}%, portata {1}, impatto massimo {2}.",
    "pl.t.replanning": "Il modello locale sta preparando alternative; compaiono sotto Modifiche proposte.",
    "pl.ev.proposed": "Nuova proposta: {0}",
    "pl.ev.replan": "{0} alternative pronte da rivedere.",
    "pl.ev.replanfail": "Non è stato possibile preparare il nuovo piano: {0}",
    "pl.ev.offer": "Un compito ha bisogno di te: {0}",
    "pl.ev.applied": "Modifica applicata.",
    "pl.ev.autoapplied": "Il piano è stato aggiornato da solo dopo un evento.",
    "pl.ev.autoparked": "Il piano è stato aggiornato da solo dopo un evento; una parte aspetta te.",
    "pl.set": "Filtro nel cloud e privacy",
    "pl.set.help": "La valutazione degli eventi può usare Jev di TypeSafe, un servizio cloud. È spenta finché non la consenti. Quando è accesa, partono solo i campi del piano spuntati qui sotto, insieme agli eventi; i nomi delle persone sono sostituiti da etichette a meno che tu tolga quella opzione.",
    "pl.set.key.yes": "Una chiave di Jev è pronta all'uso (dal campo qui sotto o dall'ambiente del server, TYPESAFE_API_KEY).",
    "pl.badnum": "Controlla i numeri: la soglia, i secondi e gli eventi per richiesta devono essere numeri.",
    "pl.set.key.no": "Nessuna chiave: inseriscila nel campo qui sotto, oppure nell'ambiente del server (TYPESAFE_API_KEY). Senza chiave il filtro nel cloud non si può accendere.",
    "pl.set.key.saved": "Una chiave Jev è salvata su questo PC (nel deposito delle credenziali, non viene più mostrata).",
    "pl.set.key.unused": "La chiave Jev salvata non è ancora usata: nella scheda Providers di Modelli, di' di sì a \"Plan events (triage)\" per un fornitore fuori da questo PC.",
    "pl.set.key.field": "Chiave di Jev (TypeSafe AI)",
    "pl.set.key.field.help": "Incolla la chiave e premi Salva. Resta nel deposito delle credenziali insieme alle chiavi degli altri fornitori, non viene più mostrata né scritta in nessun log. Lascia vuoto per tenere quella che hai.",
    "pl.set.key.remove": "Togli la chiave salvata",
    "pl.set.threshold": "Probabilità di blocco che sveglia il modello",
    "pl.set.threshold.help": "Un numero da 0 a 1 (0,80 è l'80%). Quando il filtro stima che un evento blocchi il piano con una probabilità sopra questo valore, il modello viene svegliato. Più basso lo sveglia più spesso, 1 solo con gli altri segnali.",
    "pl.set.timeout": "Secondi di attesa del cloud",
    "pl.set.timeout.help": "Quanto può durare una chiamata al filtro nel cloud prima che risponda al suo posto il filtro locale a parole chiave (predefinito 5). Alzalo con una connessione lenta.",
    "pl.set.chunk": "Eventi per richiesta al cloud",
    "pl.set.chunk.help": "Un gruppo più lungo parte in richieste di tanti eventi, e vale la risposta peggiore (predefinito 20). Abbassalo se il servizio rifiuta le richieste lunghe.",
    "pl.set.cloud": "Consenti il filtro nel cloud",
    "pl.set.pseudo": "Sostituisci i nomi delle persone con etichette, e togli indirizzi e-mail e numeri di telefono, prima dell'invio",
    "pl.set.fields": "Campi del piano che possono partire",
    "pl.set.gate": "Quando il filtro sveglia il modello",
    "pl.set.gate.or": "Un qualsiasi segnale forte (predefinito)",
    "pl.set.gate.and": "Solo un blocco forte che sia anche grave",
    "pl.set.gate.help": "Un qualsiasi segnale forte: probabilità di blocco sopra la soglia impostata qui sotto, oppure tutto il gruppo di eventi coinvolto, oppure l'evento più forte grave o critico. L'altra scelta richiede anche un impatto grave o critico, o tutto il gruppo coinvolto: il modello viene svegliato meno spesso da eventi che il filtro giudica rilevanti ma di poco conto, e un evento grave giudicato sotto la soglia non lo sveglia più.",
    "pl.set.auto": "Applica le modifiche in automatico, tranne se coinvolgono persone, prenotazioni o risorse che non controllo",
    "pl.set.auto.help": "Accesa di default. Quando un evento o la Chat modifica un piano, la modifica è applicata subito e scritta nella cronologia; il piano va avanti. Resta in Modifiche proposte, in attesa di te, solo il passo che coinvolge altre persone (un passo per qualcun altro, una telefonata da preparare), una prenotazione o un pagamento già fatti, o una risorsa che non si può modificare in automatico; il resto del piano prosegue. Spegnila per approvare ogni proposta da te. Le modifiche chieste in una Chat che non è al livello Automatico restano confermate lì.",
    "pl.set.pump": "Valuta da sola gli eventi in arrivo",
    "pl.set.pump.help": "Gli eventi che arrivano nella casella del server (POST /api/plans/events) o dalle fonti qui sotto sono raccolti per piano e valutati quando ne sono arrivati 10 o sono passati 5 minuti. Se il filtro dice di svegliare, il modello locale prepara delle proposte; vengono applicate come dice l'impostazione qui sotto. Accesa di default: parte con il server e dorme finché non arriva nulla; spegnila per non valutare più gli eventi.",
    "pl.risk.pump": "Gli eventi in arrivo saranno valutati di continuo e, con il filtro nel cloud consentito, vanno al servizio cloud, con i nomi sostituiti se l'hai lasciato attivo.",
    "pl.set.sources": "Fonti di eventi (JSON)",
    "pl.set.sources.help": "Solo lettura. Un feed: {\"kind\": \"rss\", \"url\": \"https://...\"}. Una casella di posta: {\"kind\": \"imap\", \"host\": \"...\", \"login_entry\": \"nome di un Accesso nel Portafoglio\"}: si leggono mittente, oggetto e corpo in testo semplice, senza segnare i messaggi come letti. Un bot Telegram: {\"kind\": \"telegram\", \"secret_entry\": \"nome di un Segreto nel Portafoglio\", \"allowed_chat_ids\": [123]}. Password e token restano nel Portafoglio. Questo PC: {\"kind\": \"system\", \"disk_path\": \"C:\\\\\", \"min_free_gb\": 5} avvisa quando lo spazio libero scende sotto il limite; {\"kind\": \"deadlines\", \"lead_days\": [7, 3, 1, 0]} avvisa quando un piano con date sta per iniziare o finire.",
    "pl.set.personal.help": "Parte di base, perché è ciò che permette al filtro di capire che un evento conta per una malattia, un'allergia o il lavoro di qualcuno nel piano. Sono dati personali e, con il filtro nel cloud acceso, escono da questo PC (con i nomi sostituiti). Toglila per tenerla qui: il filtro giudicherà quegli eventi peggio.",
    "pl.risk.personal": "Salute, allergie e vincoli personali dei partecipanti andranno al servizio cloud, con i nomi sostituiti se l'hai lasciato attivo.",
    "pl.card.titolo": "Titolo",
    "pl.dec.exits": "Uscite (almeno due)",
    "pl.dec.help": "Una decisione prende le uscite la cui condizione vale. Scrivi ogni condizione sui valori del piano, per esempio len(invitati_confermati) >= 2; ogni uscita diventa un passo.",
    "pl.dec.exit.title": "Uscita {0}: il passo da fare",
